import sys

def solve():
    data = list(map(int, sys.stdin.read().split()))
    idx = 0
    t = data[idx]; idx += 1
    out = []
    for _ in range(t):
        n = data[idx]; idx += 1
        a = data[idx:idx + n]; idx += n
        total = sum(a)
        if total == 0:
            out.append("0")
            continue
        for r in range(n, 0, -1):
            if total % r == 0:
                target = total // r
                cur = 0
                ok = True
                for x in a:
                    cur += x
                    if cur > target:
                        ok = False
                        break
                    if cur == target:
                        cur = 0
                if ok:
                    out.append(str(n - r))
                    break
    print("\n".join(out))

if __name__ == "__main__":
    solve()

