#include <iostream>
#include <vector>
using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int> a(n);
    int total = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        total += a[i];
    }
    for (int r = n; r >= 1; r--) {
        if (total % r == 0) {
            int target = total / r;
            int cur = 0;
            bool ok = true;
            for (int x : a) {
                cur += x;
                if (cur > target) {
                    ok = false;
                    break;
                }
                if (cur == target) {
                    cur = 0;
                }
            }
            if (ok) {
                cout << n - r << '\n';
                return;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) solve();
    return 0;
}

